function validate([grid, row, col, color]) {
  if (grid.length < 1 || grid.length > 50) return 'grid needs 1 to 50 rows.';
  if (grid.some(line => line.length !== grid[0].length)) return 'Every row of grid has the same length.';
  if (grid[0].length < 1 || grid[0].length > 50) return 'grid needs 1 to 50 columns.';
  if (grid.some(line => line.some(v => v < 1 || v > 1000))) return 'Every cell color is between 1 and 1000.';
  if (color < 1 || color > 1000) return 'color is between 1 and 1000.';
  if (row < 0 || row >= grid.length || col < 0 || col >= grid[0].length) return 'row and col must point inside grid.';
  return null;
}

