function colorBorder(grid, row, col, color) {
  // Label the component with a breadth-first search, then test every cell of the grid.
  const m = grid.length, n = grid[0].length, start = grid[row][col];
  const inside = new Set([row * n + col]);
  const queue = [[row, col]];
  for (let q = 0; q < queue.length; q++) {
    const [r, c] = queue[q];
    for (const [x, y] of [[r - 1, c], [r + 1, c], [r, c - 1], [r, c + 1]]) {
      if (x >= 0 && x < m && y >= 0 && y < n && grid[x][y] === start && !inside.has(x * n + y)) {
        inside.add(x * n + y);
        queue.push([x, y]);
      }
    }
  }
  const result = grid.map(line => line.slice());
  for (let r = 0; r < m; r++) {
    for (let c = 0; c < n; c++) {
      if (!inside.has(r * n + c)) continue;
      const edge = r === 0 || c === 0 || r === m - 1 || c === n - 1;
      const outsideNeighbour = [[r - 1, c], [r + 1, c], [r, c - 1], [r, c + 1]].some(([x, y]) => x >= 0 && x < m && y >= 0 && y < n && !inside.has(x * n + y));
      if (edge || outsideNeighbour) result[r][c] = color;
    }
  }
  return result;
}

