function generate(rand, size) {
  const large = size === 'large';
  const m = large ? 40 + Math.floor(rand() * 11) : 1 + Math.floor(rand() * 5);
  const n = large ? 40 + Math.floor(rand() * 11) : 1 + Math.floor(rand() * 5);
  // Few colors make big, irregular components; one dominant color makes components with holes.
  const palette = Array.from({ length: 1 + Math.floor(rand() * 3) }, () => large ? 1 + Math.floor(rand() * 1000) : 1 + Math.floor(rand() * 4));
  const bias = rand();
  const pick = () => rand() < bias ? palette[0] : palette[Math.floor(rand() * palette.length)];
  const grid = Array.from({ length: m }, () => Array.from({ length: n }, pick));
  const row = Math.floor(rand() * m);
  const col = Math.floor(rand() * n);
  // Sometimes the new color equals the component's own color.
  const color = rand() < 0.15 ? grid[row][col] : large ? 1 + Math.floor(rand() * 1000) : 1 + Math.floor(rand() * 5);
  return [grid, row, col, color];
}
